var data=[{"l":"Rival élu, choc éco.","v":76,"g":0},{"l":"Incidence sur le plan","v":75,"g":0},{"l":"Veulent des conseils","v":73,"g":0},{"l":"Plus anxieux","v":56,"g":0},{"l":"Ont déjà modifié","v":40,"g":1,"pill":"40\u00a0% ONT AGI"},{"l":"Moins de risque","v":15,"g":1},{"l":"Secteurs diversifiés","v":13,"g":1},{"l":"Sécurité sociale","v":42,"g":2},{"l":"Commerce et douanes","v":36,"g":2,"note":"Voie canadienne"},{"l":"Coûts de santé","v":33,"g":2},{"l":"Politique fiscale","v":29,"g":2},{"l":"Dépenses fédérales","v":28,"g":2}];
