var PW = 680 - margin.left - margin.right, PH = 300 - margin.top - margin.bottom, MT = margin.top;
var n = data.length, gap = 4;
var barH = Math.floor((PH - (n-1)*gap) / n);
if (n*barH + (n-1)*gap > PH) throw new Error("bar geometry exceeds PH");
