[0, 3, 6, 9, 12, 15, 18, lastI].forEach(function(i){
  svg.appendChild(tx(data[i].m, {x: xp(i), y: MT + PH + 14, "text-anchor": "middle", "font-size": "8", fill: "#999999"}));
});
svg.appendChild(tx("Clôture quotidienne, dollars US le baril", {x: margin.left + PW / 2, y: MT + PH + 30, "text-anchor": "middle", "font-size": "8", fill: "#999999"}));
