svg.appendChild(tx("MOY. PÉRIODE", {x: margin.left + 10, y: yp(avg) - 5, "text-anchor": "start", "font-size": "7", "font-weight": "700", fill: "#6b7280"}));
/* band label */
svg.appendChild(tx("REMONTÉE FIN OCT.", {x: xp(bandA) + (xp(bandB) - xp(bandA)) / 2, y: MT + 9, "text-anchor": "middle", "font-size": "7", "font-weight": "700", fill: "#a87408"}));
