/* axis labels */
ticks.forEach(function(v){
  svg.appendChild(tx(fmt(v, 0), {x: margin.left - 6, y: yp(v) + 3, "text-anchor": "end", "font-size": "8.5", fill: "#aaaaaa"}));
});
[0, 3, 6, 9, 12, 15, 18, 21, lastI].forEach(function(i){
  svg.appendChild(tx(data[i].m, {x: xp(i), y: MT + PH + 14, "text-anchor": "middle", "font-size": "8", fill: "#999999"}));
});
svg.appendChild(tx("Clôture quotidienne, points de l’indice", {x: margin.left + PW / 2, y: MT + PH + 30, "text-anchor": "middle", "font-size": "8", fill: "#999999"}));
/* reference label, hung above its own line at the quiet left edge */
svg.appendChild(tx("NIV. 29 SEPT.", {x: margin.left + 10, y: yp(base) - 5, "text-anchor": "start", "font-size": "7", "font-weight": "700", fill: "#6b7280"}));
/* band label */
svg.appendChild(tx("DEPUIS LA HAUSSE", {x: xp(bandA) + (xp(bandB) - xp(bandA)) / 2, y: MT + 9, "text-anchor": "middle", "font-size": "7", "font-weight": "700", fill: "#c0392b"}));
/* annotations derived from the data */
svg.appendChild(tx(data[minI].m.toUpperCase() + " BAS", {x: xp(minI), y: yp(minV) + 14, "text-anchor": "middle", "font-size": "7.5", fill: "#444444"}));
svg.appendChild(tx(data[maxI].m.toUpperCase() + " HAUT", {x: xp(maxI), y: yp(maxV) - 8, "text-anchor": "middle", "font-size": "7.5", fill: "#444444"}));
